    // Verifies the quad tree represents the grid and is minimal (a leaf exactly when the region is uniform).
    private static void Verify(int[][] grid, Node node, int r, int c, int size)
    {
        Assert.NotNull(node);
        var first = grid[r][c];
        var uniform = true;
        for (var i = r; i < r + size; i++)
            for (var j = c; j < c + size; j++)
                if (grid[i][j] != first) uniform = false;
        Assert.Equal(uniform, node.isLeaf);
        if (uniform)
        {
            Assert.Equal(first == 1, node.val);
            Assert.True(node.topLeft == null && node.topRight == null && node.bottomLeft == null && node.bottomRight == null);
            return;
        }
        var h = size / 2;
        Verify(grid, node.topLeft, r, c, h);
        Verify(grid, node.topRight, r, c + h, h);
        Verify(grid, node.bottomLeft, r + h, c, h);
        Verify(grid, node.bottomRight, r + h, c + h, h);
    }
    private static void Check(params int[][] grid) => Verify(grid, new Solution().Construct(grid), 0, 0, grid.Length);
    [Fact] public void Example1() => Check(new[] { 0, 1 }, new[] { 1, 0 });
    [Fact]
    public void Example2() => Check(
        new[] { 1, 1, 1, 1, 0, 0, 0, 0 }, new[] { 1, 1, 1, 1, 0, 0, 0, 0 }, new[] { 1, 1, 1, 1, 1, 1, 1, 1 }, new[] { 1, 1, 1, 1, 1, 1, 1, 1 },
        new[] { 1, 1, 1, 1, 0, 0, 0, 0 }, new[] { 1, 1, 1, 1, 0, 0, 0, 0 }, new[] { 1, 1, 1, 1, 0, 0, 0, 0 }, new[] { 1, 1, 1, 1, 0, 0, 0, 0 });
    [Fact] public void Single() => Check(new[] { 1 });
